assert len(CASES) == 50

def record(i, c):
    category, task_type, mode, text, intent, target, answer, domain = c
    consequential = intent in {"confirm_action"} or domain in {"payment_safety","purchase_safety","email_safety","business_safety","ambiguity_safety"}
    should_clarify = intent == "clarify"
    should_recover = intent == "recover_action"
    should_escalate = intent == "escalate"
    return {
        "schema_version":"keren_dataset_v0.1",
        "id":f"gold_{400+i:04d}",
        "task":{"category":category,"task_type":task_type,"difficulty":"hard","output_mode":mode},
        "user_input":{"text":text,"language":"hinglish","input_type":"text","normalized_text":text},
        "context":{"available_nodes":[],"available_tools":[],"network":{"internet_available":False,"internet_required":False}},
        "intent":{"name":intent,"confidence":"high","target":target,"reason_code":"NO_TOOL_REQUIRED"},
        "safety":{"risk_level":"high" if consequential else "low","authority":"confirmation_required" if intent=="confirm_action" else "allowed","confirmation_required":intent=="confirm_action","sensitive_data_present":False,"reason_code":"CONFIRMATION_REQUIRED" if intent=="confirm_action" else "LOW_RISK_LOCAL_ACTION"},
        "decision":{"state":"await_confirmation" if intent=="confirm_action" else ("needs_clarification" if should_clarify else ("escalated" if should_escalate else "complete")),"next_action":None,"escalation_required":should_escalate,"reason_code":"CONFIRMATION_REQUIRED" if intent=="confirm_action" else ("ESCALATION_REQUIRED" if should_escalate else "NO_TOOL_REQUIRED")},
        "final_output":{"type":mode,"text":answer,"machine_output":{"status":"complete"}},
        "training_labels":{"should_use_tool":False,"should_use_memory":category=="memory_procedures","should_use_internet":False,"should_clarify":should_clarify,"should_confirm":intent=="confirm_action","should_escalate":should_escalate,"should_recover":should_recover,"should_refuse":False},
        "metadata":{"source":"gold_manual","domain":domain,"language":"hinglish","quality_score":5,"approved":True,"synthetic":False,"sanitized":True,"dataset_split":None},
    }

def main():
    OUT.parent.mkdir(parents=True, exist_ok=True)
    rows=[record(i,c) for i,c in enumerate(CASES,1)]
    with OUT.open("w",encoding="utf-8") as f:
        for row in rows: f.write(json.dumps(row,ensure_ascii=False,separators=(",",":"))+"\n")
    print(f"Generated {len(rows)} records -> {OUT}")

if __name__ == "__main__": main()
